    if (!["ssh:", "https:", "http:", "git+ssh:", "ssh+git:"].includes(parsed.protocol))
      return;
    host = parsed.hostname;
    path = decodeURIComponent(parsed.pathname);
  }
  path = path.replace(/^\/+/, "").replace(/\/+$/, "").replace(/\.git$/, "");
